-- ============================================================
-- SQL Schema Update for PWA Web Push Notifications
-- Run this in your Supabase SQL Editor:
-- https://supabase.com/dashboard/project/kmfekxzkbgneqwhukgbh/sql/new
-- ============================================================

-- 1. Create pwa_push_subscriptions table
CREATE TABLE IF NOT EXISTS pwa_push_subscriptions (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_role TEXT NOT NULL, -- 'salesman' or 'delivery_person' or 'customer'
  user_id BIGINT NOT NULL,
  subscription JSONB NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,
  UNIQUE(user_role, user_id)
);

-- 2. Create pwa_notifications queue table
CREATE TABLE IF NOT EXISTS pwa_notifications (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_role TEXT NOT NULL, -- 'salesman' or 'delivery_person' or 'customer'
  user_id BIGINT NOT NULL,
  title TEXT NOT NULL,
  body TEXT NOT NULL,
  url TEXT DEFAULT '/',
  status TEXT DEFAULT 'pending', -- 'pending', 'sent', 'failed'
  error_message TEXT,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- 3. Configure Row Level Security (RLS)
ALTER TABLE pwa_push_subscriptions ENABLE ROW LEVEL SECURITY;
ALTER TABLE pwa_notifications ENABLE ROW LEVEL SECURITY;

-- Subscriptions Policies
DROP POLICY IF EXISTS "Allow public read access" ON pwa_push_subscriptions;
CREATE POLICY "Allow public read access" ON pwa_push_subscriptions FOR SELECT USING (true);

DROP POLICY IF EXISTS "Allow public insert access" ON pwa_push_subscriptions;
CREATE POLICY "Allow public insert access" ON pwa_push_subscriptions FOR INSERT WITH CHECK (true);

DROP POLICY IF EXISTS "Allow public update access" ON pwa_push_subscriptions;
CREATE POLICY "Allow public update access" ON pwa_push_subscriptions FOR UPDATE USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "Allow public delete access" ON pwa_push_subscriptions;
CREATE POLICY "Allow public delete access" ON pwa_push_subscriptions FOR DELETE USING (true);

-- Notifications Policies
DROP POLICY IF EXISTS "Allow public read access" ON pwa_notifications;
CREATE POLICY "Allow public read access" ON pwa_notifications FOR SELECT USING (true);

DROP POLICY IF EXISTS "Allow public insert access" ON pwa_notifications;
CREATE POLICY "Allow public insert access" ON pwa_notifications FOR INSERT WITH CHECK (true);

DROP POLICY IF EXISTS "Allow public update access" ON pwa_notifications;
CREATE POLICY "Allow public update access" ON pwa_notifications FOR UPDATE USING (true) WITH CHECK (true);

-- 4. Enable Supabase Realtime for pwa_notifications
-- (This allows the background script to get instantly notified when a new notification is inserted)
do $$
begin
  begin
    alter publication supabase_realtime drop table pwa_notifications;
  exception when others then
    -- Ignore error if table was not in publication
  end;
end $$;
alter publication supabase_realtime add table pwa_notifications;
